SELECT FROM ebk_book_bas
AND (title LIKE CONCAT('%', #{keyword}, '%') OR publisher LIKE CONCAT('%', #{keyword}, '%') OR copyright_owner LIKE CONCAT('%', #{keyword}, '%'))
AND book_type = #{bookType}
AND active_yn = #{activeYn}
ORDER BY book_id DESC

SELECT EXISTS(
SELECT 1 FROM ebk_book_bas
WHERE isbn = #{isbn}
)

SELECT EXISTS(
SELECT 1 FROM ebk_book_bas
WHERE isbn = #{isbn}
AND book_id != #{id}
)

